/* tests/test_gguf.c -- exercises src/gguf.c against the tiny handcrafted
 * fixtures in tests/data/ (generated by tests/data/make_fixtures.py; see
 * that script's docstring for the exact byte layout of each one).
 *
 * Positive-path assertions run in-process. Every assertion that must
 * observe fatal() (malformed files, or a valid file used through the wrong
 * getter) uses the spawn-self pattern from tests/test_common.c: fatal()
 * calls exit(1) directly, so the only way to observe "did this call fatal
 * the way we expect" from a test that must keep running afterwards is to
 * run that one call in a child process and inspect its exit code + stderr
 * from the outside. See spawn_scenario() below and gguf_test_child_main's
 * dispatch table for the full scenario list.
 *
 * All fixture paths are repo-root-relative ("tests/data/..."); every test
 * binary in this project is built and run assuming CWD == repo root (see
 * tests/run_tests.sh and scripts/wsl-check.sh, neither of which cd's into
 * the build dir before invoking a binary).
 */
#include "common.h"

#include "gguf.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef _WIN32
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#endif

#define FIXTURE(name_) "tests/data/" name_

/* ===========================================================================
 * Child-mode dispatch: `<this binary> --scenario <name>` performs exactly
 * one API call expected to fatal(), then (if it didn't) prints a note and
 * exits 0. Exit 0 / non-"fatal: " stderr both correctly fail the parent's
 * assertion -- see assert_scenario_fatals().
 * ===========================================================================
 */
static int gguf_test_child_main(int argc, char** argv) {
    if (argc < 3 || strcmp(argv[1], "--scenario") != 0) {
        fprintf(stderr, "test_gguf child: bad invocation (want --scenario <name>)\n");
        return 2;
    }
    const char* s = argv[2];
    GgufFile* f;

    /* ---- file-level negative fixtures (each must fatal inside gguf_open) ---- */
    if (strcmp(s, "bad_magic") == 0) {
        f = gguf_open(FIXTURE("bad_magic.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "bad_version") == 0) {
        f = gguf_open(FIXTURE("bad_version.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "truncated_header") == 0) {
        f = gguf_open(FIXTURE("truncated_header.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "kv_count_overflow") == 0) {
        f = gguf_open(FIXTURE("kv_count_overflow.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "tensor_count_overflow") == 0) {
        f = gguf_open(FIXTURE("tensor_count_overflow.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "array_count_overflow") == 0) {
        f = gguf_open(FIXTURE("array_count_overflow.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "misaligned_tensor") == 0) {
        f = gguf_open(FIXTURE("misaligned_tensor.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "string_len_exceeds_file") == 0) {
        f = gguf_open(FIXTURE("string_len_exceeds_file.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "key_len_exceeds_file") == 0) {
        f = gguf_open(FIXTURE("key_len_exceeds_file.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "tensor_name_len_exceeds_file") == 0) {
        f = gguf_open(FIXTURE("tensor_name_len_exceeds_file.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "n_dims_too_large") == 0) {
        f = gguf_open(FIXTURE("n_dims_too_large.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "bad_value_type") == 0) {
        f = gguf_open(FIXTURE("bad_value_type.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "unsupported_ggml_type") == 0) {
        f = gguf_open(FIXTURE("unsupported_ggml_type.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "array_of_arrays") == 0) {
        f = gguf_open(FIXTURE("array_of_arrays.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "tensor_data_exceeds_file") == 0) {
        f = gguf_open(FIXTURE("tensor_data_exceeds_file.gguf"));
        gguf_close(f);
    } else if (strcmp(s, "nonexistent_file") == 0) {
        f = gguf_open(FIXTURE("does_not_exist_intentionally.gguf"));
        gguf_close(f);

    /* ---- API-misuse on a VALID file (wrong getter / OOB / missing key) ---- */
    } else if (strcmp(s, "meta_i64_on_string_key") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_i64(f, "s.str");
        gguf_close(f);
    } else if (strcmp(s, "meta_str_on_int_key") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_str(f, "s.u32");
        gguf_close(f);
    } else if (strcmp(s, "meta_f32_on_int_key") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_f32(f, "s.u32");
        gguf_close(f);
    } else if (strcmp(s, "meta_f32_on_float64_key") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_f32(f, "s.f64");
        gguf_close(f);
    } else if (strcmp(s, "meta_i64_on_u64_exceeding_int64_max") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_i64(f, "s.u64_big");
        gguf_close(f);
    } else if (strcmp(s, "meta_i64_on_missing_key") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_i64(f, "nope.key");
        gguf_close(f);
    } else if (strcmp(s, "meta_str_on_missing_key") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_str(f, "nope.key");
        gguf_close(f);
    } else if (strcmp(s, "meta_arr_len_on_missing_key") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_arr_len(f, "nope.key");
        gguf_close(f);
    } else if (strcmp(s, "meta_arr_str_oob_index") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_arr_str(f, "a.str", 3); /* len==3, valid idx 0..2 */
        gguf_close(f);
    } else if (strcmp(s, "meta_arr_i64_on_string_array") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_arr_i64(f, "a.str", 0); /* elem type STRING, not integer */
        gguf_close(f);
    } else if (strcmp(s, "meta_arr_str_on_int_array") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_arr_str(f, "a.i32", 0); /* elem type INT32, not STRING */
        gguf_close(f);
    } else if (strcmp(s, "tensor_oob_index") == 0) {
        f = gguf_open(FIXTURE("valid_minimal.gguf"));
        (void)gguf_tensor(f, 1); /* tensor_count==1, valid idx is 0 only */
        gguf_close(f);
    } else if (strcmp(s, "tensor_by_name_missing") == 0) {
        f = gguf_open(FIXTURE("valid_minimal.gguf"));
        (void)gguf_tensor_by_name(f, "does-not-exist");
        gguf_close(f);
    } else if (strcmp(s, "meta_key_oob_index") == 0) {
        f = gguf_open(FIXTURE("valid_minimal.gguf"));
        (void)gguf_meta_key(f, 2); /* meta_count==2, valid idx 0..1 */
        gguf_close(f);
    } else if (strcmp(s, "meta_arr_elem_type_on_scalar_key") == 0) {
        f = gguf_open(FIXTURE("valid_types.gguf"));
        (void)gguf_meta_arr_elem_type(f, "s.u32");
        gguf_close(f);
    } else {
        fprintf(stderr, "test_gguf child: unknown scenario '%s'\n", s);
        return 2;
    }

    printf("test_gguf child: scenario '%s' did NOT fatal\n", s);
    return 0;
}
#define TEST_CHILD_MAIN gguf_test_child_main
#include "test.h"

/* ===========================================================================
 * Spawn helper -- mirrors tests/test_common.c's fatal_exits_nonzero_with_
 * stderr_prefix test exactly, including the Windows cmd.exe outer-quote
 * fix (see that test's comment for the full quoting proof; this repo lives
 * under a path with a space, "...\New Drive\...", so it applies here too).
 * ===========================================================================
 */
static int spawn_scenario(const char* scenario, char* err_buf, size_t err_buf_sz) {
#ifdef _WIN32
    char exe_path_buf[4096];
    DWORD full_len = GetFullPathNameA(g_test_argv0, (DWORD)sizeof exe_path_buf,
                                       exe_path_buf, NULL);
    if (full_len == 0 || full_len >= sizeof exe_path_buf) {
        fatal("test_gguf: GetFullPathNameA failed for '%s'", g_test_argv0);
    }
    const char* exe_path = exe_path_buf;
#else
    const char* exe_path = g_test_argv0;
#endif

    char errfile[4200];
    char inner[8600];
    char cmd[8800];

    snprintf(errfile, sizeof errfile, "%s.%s.stderr", exe_path, scenario);
    snprintf(inner, sizeof inner, "\"%s\" --scenario %s 2>\"%s\"", exe_path,
              scenario, errfile);

#ifdef _WIN32
    snprintf(cmd, sizeof cmd, "\"%s\"", inner); /* extra outer quote pair */
#else
    snprintf(cmd, sizeof cmd, "%s", inner);
#endif

    int rc = system(cmd);

    err_buf[0] = '\0';
    FILE* ef = fopen(errfile, "rb");
    if (ef) {
        size_t n = fread(err_buf, 1, err_buf_sz - 1, ef);
        err_buf[n] = '\0';
        fclose(ef);
        remove(errfile);
    }
    return rc;
}

static void assert_scenario_fatals(const char* scenario, const char* msg_substr) {
    char errbuf[1024];
    int rc = spawn_scenario(scenario, errbuf, sizeof errbuf);
    ASSERT_TRUE(rc != 0);
    ASSERT_TRUE(strncmp(errbuf, "fatal: ", 7) == 0);
    if (msg_substr != NULL && strstr(errbuf, msg_substr) == NULL) {
        fprintf(stderr,
                "FAIL %s:%d: scenario '%s': stderr did not contain \"%s\" "
                "(got: %s)\n",
                __FILE__, __LINE__, scenario, msg_substr, errbuf);
        g_test_case_failed = 1;
    }
}

/* ===========================================================================
 * Positive-path tests (in-process)
 * ===========================================================================
 */

TEST(open_close_minimal_file_succeeds) {
    GgufFile* f = gguf_open(FIXTURE("valid_minimal.gguf"));
    ASSERT_TRUE(f != NULL);
    gguf_close(f);
}

TEST(minimal_file_metadata_str_and_i64) {
    GgufFile* f = gguf_open(FIXTURE("valid_minimal.gguf"));
    ASSERT_TRUE(gguf_meta_has(f, "general.architecture"));
    ASSERT_TRUE(gguf_meta_has(f, "general.block_count"));
    ASSERT_TRUE(!gguf_meta_has(f, "does.not.exist"));
    ASSERT_EQ_STR(gguf_meta_str(f, "general.architecture"), "test");
    ASSERT_EQ_I64(gguf_meta_i64(f, "general.block_count"), 4);
    gguf_close(f);
}

TEST(minimal_file_meta_enumeration) {
    GgufFile* f = gguf_open(FIXTURE("valid_minimal.gguf"));
    ASSERT_EQ_I64(gguf_meta_count(f), 2);
    ASSERT_EQ_STR(gguf_meta_key(f, 0), "general.architecture");
    ASSERT_EQ_STR(gguf_meta_key(f, 1), "general.block_count");
    ASSERT_EQ_U32(gguf_meta_type(f, "general.architecture"), GGUF_TYPE_STRING);
    ASSERT_EQ_U32(gguf_meta_type(f, "general.block_count"), GGUF_TYPE_UINT32);
    gguf_close(f);
}

TEST(minimal_file_tensor_accessors_and_data_bytes) {
    GgufFile* f = gguf_open(FIXTURE("valid_minimal.gguf"));
    ASSERT_EQ_I64(gguf_tensor_count(f), 1);

    const GgufTensor* t = gguf_tensor(f, 0);
    ASSERT_TRUE(t != NULL);
    ASSERT_EQ_STR(t->name, "weight");
    ASSERT_EQ_U32(t->type, GGUF_GGML_TYPE_F32);
    ASSERT_EQ_U32(t->n_dims, 1);
    ASSERT_EQ_I64(t->dims[0], 4);
    ASSERT_EQ_I64(t->nbytes, 16); /* 4 elements * 4 bytes, F32 */
    ASSERT_EQ_I64(t->offset, 0);

    const u8* bytes = (const u8*)t->data;
    ASSERT_TRUE(bytes != NULL);
    int data_ok = 1;
    for (int i = 0; i < 16; i++) {
        if (bytes[i] != (u8)i) data_ok = 0;
    }
    ASSERT_TRUE(data_ok);

    const GgufTensor* by_name = gguf_tensor_by_name(f, "weight");
    ASSERT_TRUE(by_name == t);

    gguf_close(f);
}

TEST(types_file_scalar_getters_widen_every_integer_type) {
    GgufFile* f = gguf_open(FIXTURE("valid_types.gguf"));
    ASSERT_EQ_STR(gguf_meta_str(f, "s.str"), "hello");
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.u32"), 42);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.i32"), -7);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.u64"), 123456789012LL);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.i64"), -123456789012LL);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.bool_t"), 1);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.bool_f"), 0);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.u8"), 200);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.i8"), -100);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.u16"), 50000);
    ASSERT_EQ_I64(gguf_meta_i64(f, "s.i16"), -30000);
    f32 v = gguf_meta_f32(f, "s.f32");
    ASSERT_TRUE(v > 3.4999f && v < 3.5001f);
    gguf_close(f);
}

