static int all_bytes_equal(const void* p, u64 n, u8 want) {
    const u8* b = (const u8*)p;
    for (u64 i = 0; i < n; i++) {
        if (b[i] != want) return 0;
    }
    return 1;
}

TEST(multi_tensor_file_alignment_override_via_i64_or) {
    GgufFile* f = gguf_open(FIXTURE("valid_multi_tensor.gguf"));
    ASSERT_EQ_I64(gguf_meta_i64_or(f, "general.alignment", 32), 16);
    gguf_close(f);
}

TEST(multi_tensor_file_order_types_and_data_bytes) {
    GgufFile* f = gguf_open(FIXTURE("valid_multi_tensor.gguf"));
    ASSERT_EQ_I64(gguf_tensor_count(f), 3);

    const GgufTensor* a = gguf_tensor(f, 0);
    const GgufTensor* b = gguf_tensor(f, 1);
    const GgufTensor* c = gguf_tensor(f, 2);
    ASSERT_EQ_STR(a->name, "a");
    ASSERT_EQ_STR(b->name, "b");
    ASSERT_EQ_STR(c->name, "c");
    ASSERT_EQ_U32(a->type, GGUF_GGML_TYPE_F32);
    ASSERT_EQ_U32(b->type, GGUF_GGML_TYPE_Q4_K);
    ASSERT_EQ_U32(c->type, GGUF_GGML_TYPE_Q6_K);
    ASSERT_EQ_I64(a->nbytes, 64);
    ASSERT_EQ_I64(b->nbytes, 144);
    ASSERT_EQ_I64(c->nbytes, 210);
    ASSERT_EQ_I64(a->offset, 0);
    ASSERT_EQ_I64(b->offset, 64);
    ASSERT_EQ_I64(c->offset, 224); /* gap 208..224 deliberately unused */

    ASSERT_TRUE(all_bytes_equal(a->data, a->nbytes, 0xAA));
    ASSERT_TRUE(all_bytes_equal(b->data, b->nbytes, 0xBB));
    ASSERT_TRUE(all_bytes_equal(c->data, c->nbytes, 0xCC));

    ASSERT_TRUE(gguf_tensor_by_name(f, "a") == a);
    ASSERT_TRUE(gguf_tensor_by_name(f, "b") == b);
    ASSERT_TRUE(gguf_tensor_by_name(f, "c") == c);

    gguf_close(f);
}

